from pyparsing import Regex, Literal, OneOrMore, Or, Optional, Empty, Group
from ute_admin_infomodel.parsing.parser import InfoModelParser


def original_condition(s, loc, token):
    """Joins parsed predicates into string"""
    return s[loc:]


def return_string(s, loc, token):
    """Return quoted string if original was guoted"""
    if token.quoted:
        return '"' + token[0] + '"'
    else:
        return token[0]


QUOT = Literal('"').suppress()
QUOTNS = Literal('"')
COLON = Literal(':').suppress()
COMMA = Literal(',').suppress()
LBRACKET = Literal("[").suppress()
RBRACKET = Literal("]").suppress()
ARROW = Literal('->').suppress()
TIMES = Literal('times').suppress()

INTEGER = Regex('0|[1-9][0-9]*')
ALPHANUM = Regex(r'[^=<>"*!:\[\]\-\ ]+')
QUOTED = (QUOT + Regex('[^"]+') + QUOT)('quoted')

dist_name = Regex(
    r'(((//)|(/))[A-Z0-9_]+-([1-9]\*\?|0|[1-9][0-9]*|\*|\[(0|[1-9][0-9]*(\,(0|[1-9][0-9]*))*)\]))+')('dist_name')
parameter_name = OneOrMore((ALPHANUM + Optional(Regex(r"\[(0|[1-9][0-9]*)\]")))).setParseAction(lambda x: ''.join(x))('name')

wildcard = Or((Literal('*'), Literal('=*'), Literal('empty'), Literal('=empty'),
               Literal('!empty'), Literal('!=empty'), Literal('!=empty'), Literal('not-empty')))('operator')
unary_operator = Or((Literal('>'), Literal('<'), Literal('>='), Literal('<='),
                     Literal('='), Literal('!='), Literal('!'), Literal('regex'), Literal('=regex')))('operator')
empty_operator = Empty().setParseAction(lambda x: "")('operator')

parameter_value = Or((ALPHANUM, QUOTED)).setParseAction(return_string)('value')

empty_value = Empty().setParseAction(lambda x: "")('value')

value_matcher = Group((wildcard + empty_value) | ((unary_operator | empty_operator) + parameter_value))
change_predicate = value_matcher('previous') + ARROW + value_matcher('new')
param_change_predicate_body = (parameter_name + Optional(COLON + change_predicate))('predicate')
param_change_predicate = (LBRACKET + param_change_predicate_body + RBRACKET).setParseAction(original_condition)('predicate')

param_value_predicate_body = (parameter_name + value_matcher('condition'))('predicate')
object_params_predicate = (LBRACKET + param_value_predicate_body + RBRACKET).setParseAction(original_condition)('predicate')

operator_value = (unary_operator + INTEGER('value'))
occurences_condition = (TIMES + operator_value).setParseAction(original_condition)('occurences_condition')

reset = Literal('reset')('action')
remove = Literal('remove')('action')
create = Literal('create')('action')
change = Literal('change')('action')
update = Literal('update')('action')


ResetEventGrammar = reset + Optional(occurences_condition)
RemoveEventGrammar = remove + dist_name + Optional(object_params_predicate) + Optional(occurences_condition)
CreateEventGrammar = create + dist_name + Optional(object_params_predicate) + Optional(occurences_condition)
ChangeEventGrammar = change + dist_name + Optional(param_change_predicate) + Optional(occurences_condition)
UpdateEventGrammar = Optional(update) + dist_name + Optional(param_change_predicate) + Optional(occurences_condition)


class InfoModelEventParser(InfoModelParser):

    def __init__(self):
        self.grammar = (Regex('^')
                        + Or((ResetEventGrammar,
                             RemoveEventGrammar,
                             CreateEventGrammar,
                             ChangeEventGrammar,
                             UpdateEventGrammar))
                        + Regex('$'))


class InfoModelEventObjectPredicateParser(InfoModelParser):

    def __init__(self):
        self.grammar = (Regex('^')
                        + LBRACKET
                        + param_value_predicate_body
                        + RBRACKET
                        + Optional(occurences_condition)
                        + Regex('$'))


class InfoModelEventParameterPredicateParser(InfoModelParser):

    def __init__(self):
        self.grammar = (Regex('^')
                        + LBRACKET
                        + param_change_predicate_body
                        + RBRACKET
                        + Optional(occurences_condition)
                        + Regex('$'))


class InfoModelConditionParser(InfoModelParser):
    def __init__(self):
        self.grammar = (Regex('^')
                        + Optional(TIMES)
                        + (operator_value | (wildcard + empty_value) | ((unary_operator | empty_operator) + parameter_value))
                        + Regex('$'))


class InfoModelValueMatcherParser(InfoModelParser):
    def __init__(self):
        self.grammar = (Regex('^')
                        + (wildcard
                        + empty_value) | ((unary_operator | empty_operator) + parameter_value)
                        + Regex('$'))
